#include "ModMenu/Workspace.h"
#include <iostream>
int main(){using namespace menu;int failures=0;auto check=[&](bool ok,char const*t){if(!ok){++failures;std::cerr<<"FAIL "<<t<<'\n';}};
 std::string raw=R"({"schemaVersion":1,"plugin":{"id":"Example","entry":"Example.dll","versions":["1"]},"pages":[{"id":"jobs","label":"Jobs","controls":[{"id":"name","type":"text","label":"Name","minBytes":0,"maxBytes":20},{"id":"start","type":"action","label":"Start","confirmation":"Proceed?"},{"id":"list","type":"list","label":"Results","selectAction":"choose"}]}]})";
 auto d=ParseWorkspace(raw,"Example","Example.dll","1");WorkspaceBroker broker;auto session=broker.Register(d);auto state=WorkspaceJson::parse(R"({"protocolVersion":1,"revision":1,"controls":{"name":{"value":"中"},"start":{"enabled":true},"list":{"rows":[{"id":"row1","label":"One"}]}}})");
 check(broker.Publish(session,state.dump()),"valid initial snapshot");std::uint32_t n=0;check(broker.Poll(session,nullptr,0,n)&&n==0,"publishing/reading does not execute a command");
 std::string error;check(broker.Submit(session,"jobs","start",1,{{"name","demo"}},"",error),"explicit action enqueues");check(!broker.Submit(session,"jobs","start",1,{{"name","demo"}},"",error),"inflight action deduplicates");
 check(broker.Poll(session,nullptr,0,n)&&n>0,"size query retains command");char shortBuffer[2]{};std::uint32_t shortN=0;check(broker.Poll(session,shortBuffer,2,shortN)&&shortN==n,"short output retains command");std::vector<char>out(n);check(broker.Poll(session,out.data(),n,shortN),"copy command");auto command=WorkspaceJson::parse(out.data());check(command["action"]=="start"&&command["values"]["name"]=="demo"&&command["revision"]==1,"literal command identity and payload");
 state["revision"]=2;state["results"]={{{"requestId",command["requestId"]},{"state","succeeded"}}};check(broker.Publish(session,state.dump()),"terminal result");check(broker.Submit(session,"jobs","start",2,{{"name","again"}},"",error),"ack releases action");check(!broker.Publish(session,state.dump()),"nonmonotonic revision refused");
 check(!broker.Submit(session,"jobs","choose",2,{{"name","again"}},"missing",error),"stale list identity refused");check(broker.Submit(session,"jobs","choose",2,{{"name","again"}},"row1",error),"stable row ID selected");
 state["revision"]=3;state["controls"]["list"]["rows"]=WorkspaceJson::array();for(int i=0;i<129;++i)state["controls"]["list"]["rows"].push_back({{"id","r"+std::to_string(i)},{"label","Row"}});check(!broker.Publish(session,state.dump()),"overlimit rows refused atomically");
 check(broker.Unregister(session)&&!broker.Publish(session,state.dump()),"stale token refused");auto second=broker.Register(d);check(second!=session,"session not reused");
 bool refused=false;try{StrictJson(R"({"a":1,"a":2})",100);}catch(...){refused=true;}check(refused,"duplicate keys refused");
 auto invalidDeclaration=[&](WorkspaceJson candidate,char const*label){bool rejected=false;try{ParseWorkspace(candidate.dump(),"Example","Example.dll","1");}catch(...){rejected=true;}check(rejected,label);};
 auto base=WorkspaceJson::parse(raw);auto invalid=base;invalid["schemaVersion"]=2;invalidDeclaration(invalid,"unknown declaration version refused");invalid=base;invalid["pages"][0]["controls"].push_back(invalid["pages"][0]["controls"][0]);invalidDeclaration(invalid,"duplicate control identity refused");invalid=base;invalid["plugin"]["versions"]={"*"};invalidDeclaration(invalid,"wildcard manifest version refused");invalid=base;invalid["pages"][0]["controls"][0]["maxBytes"]=4097;invalidDeclaration(invalid,"overlimit text declaration refused");
 WorkspaceBroker bounded;auto many=d;many.id="Bounded";many.pages[0].controls.clear();for(unsigned i=0;i<17;++i){WorkspaceControl c;c.id="a"+std::to_string(i);c.type="action";c.label.en="Action";many.pages[0].controls.push_back(c);}auto full=bounded.Register(many);WorkspaceJson complete={{"protocolVersion",1},{"revision",1},{"controls",WorkspaceJson::object()}};for(unsigned i=0;i<17;++i)complete["controls"]["a"+std::to_string(i)]={{"enabled",true}};
 check(bounded.Publish(full,complete.dump()),"queue fixture snapshot accepted");for(unsigned i=0;i<16;++i)check(bounded.Submit(full,"jobs","a"+std::to_string(i),1,WorkspaceJson::object(),"",error),"first 16 distinct requests accepted");check(!bounded.Submit(full,"jobs","a16",1,WorkspaceJson::object(),"",error),"17th request refused without overwriting earlier requests");
 for(unsigned i=0;i<16;++i){bounded.Poll(full,nullptr,0,n);std::vector<char> bytes(n);check(n&&bounded.Poll(full,bytes.data(),n,n)&&WorkspaceJson::parse(bytes.data())["action"]=="a"+std::to_string(i),"saturated queue preserves literal FIFO order");}
 check(!bounded.Submit(full,"jobs","a16",1,WorkspaceJson::object(),"",error),"polled inflight requests still count toward bound");
 auto original=bounded.Snapshots()[0].state;invalid=complete;invalid["revision"]=2;invalid["controls"]["unknown"]={{"enabled",true}};check(!bounded.Publish(full,invalid.dump())&&bounded.Snapshots()[0].state==original,"invalid state retains last immutable snapshot");invalid=complete;invalid["revision"]=2;invalid["controls"]["a0"]["busy"]="yes";check(!bounded.Publish(full,invalid.dump()),"wrong state flag type refused");
 std::string malformed="{\"x\":\"";malformed.push_back('\xff');malformed+="\"}";refused=false;try{StrictJson(malformed,100);}catch(...){refused=true;}check(refused,"malformed UTF8 refused");
 WorkspaceBroker edge;auto edgeDef=d;edgeDef.id="Edge";edgeDef.pages[0].controls.clear();WorkspaceControl start;start.id="start";start.type="action";start.label.en="Start";edgeDef.pages[0].controls.push_back(start);WorkspaceJson form=WorkspaceJson::object();for(unsigned i=0;i<8;++i){WorkspaceControl text;text.id="t"+std::to_string(i);text.type="text";text.label.en="Text";text.maxBytes=4096;edgeDef.pages[0].controls.push_back(text);form[text.id]=std::string(4096,'x');}auto edgeToken=edge.Register(edgeDef);edge.Publish(edgeToken,R"({"protocolVersion":1,"revision":1,"controls":{"start":{"enabled":true}}})");
 std::string envelope=R"({"action":"start","page":"jobs","protocolVersion":1,"requestId":1,"revision":1,"session":1,"values":)";auto excess=envelope.size()+form.dump().size()+1-32768;form["t7"]=std::string(4096-excess,'x');check(envelope.size()+form.dump().size()+1==32768,"edge fixture has 32768 JSON bytes before NUL");check(!edge.Submit(edgeToken,"jobs","start",1,form,"",error),"command requiring 32769 buffer bytes refuses before queueing");
 std::cout<<"workspace failures="<<failures<<'\n';return failures?1:0;
}
